RAW_BE.forEach(t => { t.openDt = new Date(t.open); t.closeDt = new Date(t.close); });

// ALLIN 2.0 — Configs trouvees par recherche exhaustive sur 2026 SEUL, puis appliquees
// telles quelles a TOUT l'historique (2025+2026) — choix explicite de l'utilisateur :
//  - Compte propre : base 1%, TREND inchange (jamais reduit), CONTRE coupe a 0% apres 2 SL consecutifs.
//  - Propfirm      : base 0.5%, TREND /3 apres 2 SL, CONTRE coupe a 0% apres 3 SL (optimise sur 2025+2026).
const MM_ALLIN20 = {
  cp: {trend_base:1.0, trend_t2:1.0, trend_t3:1.0, trend_trig2:2, trend_trig3:2,
       contre_base:1.0, contre_t2:0.0, contre_t3:0.0, contre_trig2:2, contre_trig3:2},
  pf: {trend_base:0.5, trend_t2:0.5/3, trend_t3:0.5/3, trend_trig2:2, trend_trig3:2,
       contre_base:0.5, contre_t2:0.0, contre_t3:0.0, contre_trig2:3, contre_trig3:3},
};

const MM_LABELS_ALLIN20 = {
  cp: {label:'Compte propre', sub:'TREND inchangé, CONTRE coupé après 2 SL — config optimisée sur 2026, appliquée à tout l\'historique', tag:'Base 1%',
       explain:'<b>Compte propre</b> — 1% de risque de base, TREND comme CONTRE. <b>TREND</b> reste toujours à 1%, aucune réduction. Dès que <b>CONTRE</b> encaisse 2 SL consécutifs (déjà clôturés), son risque passe à <b>0%</b> jusqu\'à son prochain trade non-SL. Ce réglage a été trouvé par recherche exhaustive sur 2026 seul, puis appliqué tel quel à tout l\'historique 2025+2026 — attention, sur la période complète le Max DD grimpe nettement (marché 2025 plus dur que 2026). Décision prise à l\'ouverture de chaque position, en ne regardant que les positions déjà closes à cet instant.'},
  pf: {label:'Propfirm', sub:'TREND /3 après 2 SL, CONTRE coupé après 3 SL — config optimisée sur 2025+2026', tag:'Base 0.5%',
       explain:'<b>Propfirm</b> — 0.5% de risque de base, TREND comme CONTRE. Dès que <b>TREND</b> encaisse 2 SL consécutifs, son risque est divisé par 3 (→0.167%) jusqu\'à son prochain trade non-SL. Dès que <b>CONTRE</b> encaisse 3 SL consécutifs, son risque passe à <b>0%</b> jusqu\'à son prochain trade non-SL. Ce réglage a été trouvé par recherche exhaustive directement sur tout l\'historique 2025+2026 (contrairement au Compte propre) — conçu pour rester proche de 10% de drawdown max sur la période complète.'},
};

// BE brut — Compte propre = risque flat 1% pur, aucune adaptation. Propfirm = risque
// adaptatif par signal (P/L/W), chacun regle independamment, trouve par recherche
// exhaustive sur tout l'historique 2025+2026.
const MM_BE = {
  cp: {P:[1,2], L:[1,2], W:[1,2], base: 1.0},   // diviseur=1 partout => jamais reduit (flat 1%)
  pf: {P:[1,2], L:[999,4], W:[1,2], base: 0.5},
};

const MM_LABELS_BE = {
  cp: {label:'Compte propre', sub:'Risque flat 1%, aucune adaptation', tag:'Base 1%',
       explain:'<b>Compte propre</b> — 1% de risque fixe sur chaque position du journal BE brut, sans aucune réduction ni palier. Le plus simple, le plus exposé aux séries de pertes (Max DD ≈ 30% sur l\'historique complet).'},
  pf: {label:'Propfirm', sub:'Risque adaptatif par signal (P/L/W) — config optimisée sur 2025+2026', tag:'Base 0.5%',
       explain:'<b>Propfirm</b> — 0.5% de risque de base sur chaque signal <b>P</b>, <b>L</b>, <b>W</b>, réglés indépendamment. <b>P</b> reste toujours à 0.5% (aucune réduction). <b>L</b> passe à <b>0%</b> dès qu\'il encaisse 4 SL consécutifs (déjà clôturés) sur ce même signal, jusqu\'à son prochain trade non-SL. <b>W</b> reste toujours à 0.5% (aucune réduction). Trouvé par recherche exhaustive sur tout l\'historique 2025+2026 — un réglage sans distinction de signal ne fait pas mieux que le flat sur ces données, la coupure par signal P/L/W est nécessaire.'},
};

let journal = 'allin20';
let period = 'all';
let activeSignals = new Set(['W','P','L']);
let curSrc = 'cp';
let curFilter = 'all';
let sortMode = 'close';

function curRAW(){ return journal === 'allin20' ? RAW_ALLIN20 : RAW_BE; }
function curMM(){ return journal === 'allin20' ? MM_ALLIN20 : MM_BE; }
function curLabels(){ return journal === 'allin20' ? MM_LABELS_ALLIN20 : MM_LABELS_BE; }

function fmtMoney(v){ return '$' + Math.round(v).toLocaleString('fr-FR'); }
function fmtPct(v){ return (v>=0?'+':'') + v.toFixed(2) + '%'; }
function fmtDate(d){ return d.toLocaleDateString('fr-FR'); }

function buildEvents(trades){
  const events = [];
  trades.forEach((t,i) => { events.push([t.openDt,1,i,'open']); events.push([t.closeDt,0,i,'close']); });
  events.sort((a,b) => a[0]-b[0] || a[1]-b[1]);
  return events;
}
function tier(streak, base, t2, t3, trig2, trig3){
  if(streak >= trig3) return t3;
  if(streak >= trig2) return t2;
  return base;
}
function simulateTiered(trades, mm){
  const events = buildEvents(trades);
  let capital = CAP0, trendSl = 0, contreSl = 0;
  const assigned = {};
  const curve = [];
  for(const [dt, kind, idx, label] of events){
    const t = trades[idx];
    if(label === 'open'){
      let r;
      if(t.trend === 'TREND') r = tier(trendSl, mm.trend_base, mm.trend_t2, mm.trend_t3, mm.trend_trig2, mm.trend_trig3);
      else r = tier(contreSl, mm.contre_base, mm.contre_t2, mm.contre_t3, mm.contre_trig2, mm.contre_trig3);
      assigned[idx] = r;
    } else {
      const r = assigned[idx] ?? 0;
      const rr = (t.result === 'BE') ? 0.0 : t.rr;
      capital = capital * (1 + r/100 * rr);
      const result = t.result;
      curve.push({dt, openDt:t.openDt, capital, result_g:result, trend:t.trend});
      if(t.trend === 'TREND') trendSl = (result === 'SL') ? trendSl+1 : 0;
      else contreSl = (result === 'SL') ? contreSl+1 : 0;
    }
  }
  return curve;
}
function simulatePerSignal(trades, mm){
  // mm = {P:[div,thr], L:[div,thr], W:[div,thr], base}. Chaque signal a son propre
  // streak de SL consecutifs ; des qu'il atteint son seuil, son risque passe a
  // base/diviseur jusqu'a son prochain trade non-SL de ce meme signal.
  const events = buildEvents(trades);
  let capital = CAP0;
  const streak = {P:0, L:0, W:0};
  const assigned = {};
  const curve = [];
  for(const [dt, kind, idx, label] of events){
    const t = trades[idx];
    if(label === 'open'){
      const sig = t.signal;
      const [div, thr] = mm[sig] || [1,2];
      const reduced = mm.base / div;
      assigned[idx] = (streak[sig]||0) >= thr ? reduced : mm.base;
    } else {
      const r = assigned[idx] ?? 0;
      const rr = (t.result === 'BE') ? 0.0 : t.rr;
      capital = capital * (1 + r/100 * rr);
      const result = t.result;
      curve.push({dt, openDt:t.openDt, capital, result_g:result, signal:t.signal});
      const sig = t.signal;
      streak[sig] = (result === 'SL') ? (streak[sig]||0)+1 : 0;
    }
  }
  return curve;
}
function ddEpisodes(curve){
  const episodes = [];
  let peakVal = CAP0, peakDate = curve.length ? curve[0].dt : null, cur = null;
  for(const pt of curve){
    if(pt.capital >= peakVal){
      if(cur) episodes.push(cur);
      cur = null; peakVal = pt.capital; peakDate = pt.dt;
    } else {
      const ddPct = (peakVal - pt.capital) / peakVal * 100;
      if(!cur || ddPct > cur.dd_pct) cur = {peak_date:peakDate, peak_val:peakVal, trough_date:pt.dt, trough_val:pt.capital, dd_pct:ddPct};
    }
  }
  if(cur) episodes.push(cur);
  episodes.sort((a,b) => b.dd_pct - a.dd_pct);
  return episodes;
}
function statsFromCurve(curve){
  if(!curve.length) return {perf:0, maxdd:0, over10:0};
  const finalCap = curve[curve.length-1].capital;
  const eps = ddEpisodes(curve);
  const maxdd = eps.length ? eps[0].dd_pct : 0;
  const over10 = eps.filter(e => e.dd_pct > 10).length;
  const perf = (finalCap/CAP0 - 1) * 100;
  return {perf, maxdd, over10};
}

function filteredBaseTrades(){
  return curRAW().filter(t => {
    if(t.signal && !activeSignals.has(t.signal)) return false;
    if(period === '2026' && t.openDt < new Date('2026-01-01')) return false;
    if(period === 'all' && t.openDt < new Date('2025-01-01')) return false;
    return true;
  });
}

function buildCard(curve, trades, sourceField){
  if(!curve.length) return {available:false};
  const {perf, maxdd, over10} = statsFromCurve(curve);
  const eps = ddEpisodes(curve);
  const n = curve.length;
  const nTp = curve.filter(r => r.result_g==='TP2' || r.result_g==='TP').length;
  const nSl = curve.filter(r => r.result_g==='SL').length;
  const nBe = n - nTp - nSl;
  let maxc = 0, cur = 0;
  for(const pt of curve){ if(pt.result_g==='SL'){ cur++; maxc = Math.max(maxc,cur); } else cur = 0; }
  let gains=0, losses=0, prev=CAP0;
  for(const pt of curve){ if(pt.capital>prev) gains += pt.capital-prev; else if(pt.capital<prev) losses += prev-pt.capital; prev=pt.capital; }
  const pf = losses>0 ? gains/losses : Infinity;

  const byMonth = {};
  const monthOrder = [];
  for(const pt of curve){
    const k = pt.dt.getFullYear()+'-'+String(pt.dt.getMonth()+1).padStart(2,'0');
    if(!byMonth[k]){ byMonth[k]=[]; monthOrder.push(k); }
    byMonth[k].push(pt);
  }
  let capStart = CAP0;
  const months = monthOrder.map(k => {
    const rows = byMonth[k];
    const [y,m] = k.split('-').map(Number);
    const nTpM = rows.filter(r=>r.result_g==='TP2' || r.result_g==='TP').length;
    const nSlM = rows.filter(r=>r.result_g==='SL').length;
    const endCap = rows[rows.length-1].capital;
    const pct = (endCap/capStart-1)*100;
    capStart = endCap;
    return {label: MONTH_SHORT[m]+' '+y, n: rows.length, tp:nTpM, sl:nSlM, be: rows.length-nTpM-nSlM, perf_pct: pct, cap_end: endCap};
  });

  const equity = [{dt: curve[0].dt, cap: CAP0}].concat(curve.map(pt => ({dt: pt.dt, cap: pt.capital})));

  const log = [];
  let prevCap = CAP0;
  curve.forEach((pt,i) => {
    const pct = (pt.capital/prevCap - 1) * 100;
    log.push({i:i+1, close: pt.dt, open: pt.openDt, source: pt[sourceField], result: pt.result_g==='TP2'?'TP':pt.result_g, pct, cap: pt.capital, varAmt: pt.capital-prevCap,
               month_key: pt.dt.getFullYear()+'-'+String(pt.dt.getMonth()+1).padStart(2,'0'),
               month_label: MONTH_LONG[pt.dt.getMonth()+1]+' '+pt.dt.getFullYear(),
               month_key_open: pt.openDt.getFullYear()+'-'+String(pt.openDt.getMonth()+1).padStart(2,'0'),
               month_label_open: MONTH_LONG[pt.openDt.getMonth()+1]+' '+pt.openDt.getFullYear()});
    prevCap = pt.capital;
  });

  return {
    available:true, n, n_tp:nTp, n_sl:nSl, n_be:nBe, winrate: n? nTp/n*100 : 0,
    perf_pct: perf, final_cap: curve[n-1].capital, max_dd: maxdd, profit_factor: pf, max_consec_sl: maxc,
    date_start: fmtDate(trades[0].openDt), date_end: fmtDate(trades[trades.length-1].openDt),
    months, equity, log,
    dd_over_10: eps.filter(e => e.dd_pct > 10).map(e => ({dd_pct:e.dd_pct, peak_date:e.peak_date, peak_val:e.peak_val, trough_date:e.trough_date, trough_val:e.trough_val})),
  };
}

function getCard(key){
  const trades = filteredBaseTrades();
  if(!trades.length) return {available:false};
  if(journal === 'allin20'){
    const curve = simulateTiered(trades, curMM()[key]);
    return buildCard(curve, trades, 'trend');
  } else {
    const curve = simulatePerSignal(trades, curMM()[key]);
    return buildCard(curve, trades, 'signal');
  }
}

function scaleMM(mm, j, x2) {
  if (!x2) return mm;
  const f = 2;
  if (j === 'allin20') {
    const o = {};
    ['trend_base','trend_t2','trend_t3','contre_base','contre_t2','contre_t3'].forEach(k => o[k] = mm[k] * f);
    ['trend_trig2','trend_trig3','contre_trig2','contre_trig3'].forEach(k => o[k] = mm[k]);
    return o;
  }
  return Object.assign({}, mm, { base: mm.base * f });
}

function getCardX(key, x2) {
  const trades = filteredBaseTrades();
  if (!trades.length) return { available: false };
  const mm = scaleMM(curMM()[key], journal, x2);
  if (journal === 'allin20') return buildCard(simulateTiered(trades, mm), trades, 'trend');
  return buildCard(simulatePerSignal(trades, mm), trades, 'signal');
}

export function compute(j, p, sigs, x2) {
  journal = j;
  period = p;
  activeSignals = new Set(sigs);
  return { cp: getCardX('cp', x2), pf: getCardX('pf', x2) };
}

export function labels(j) { return j === 'allin20' ? MM_LABELS_ALLIN20 : MM_LABELS_BE; }
export function counts(j) { return j === 'allin20' ? RAW_ALLIN20.length : RAW_BE.length; }
export { CAP0, MONTH_LONG, MONTH_SHORT, fmtMoney, fmtPct, fmtDate };
